def encrypt(s):
    """Encrypts a string by shifting each lowercase letter 4 positions forward in the alphabet, wrapping around if needed."""
    encrypted = []
    for c in s:
        if c.islower():
            shifted = (ord(c) - ord('a') + 4) % 26
            encrypted.append(chr(shifted + ord('a')))
        else:
            encrypted.append(c)
    return ''.join(encrypted)
