    def get_balance_and_min(s):
        balance = 0
        min_balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < min_balance:
                min_balance = balance
        return (balance, min_balance)

    b1, m1 = get_balance_and_min(s1)
    b2, m2 = get_balance_and_min(s2)

    # Check order s1 + s2
    min_order1 = min(m1, m2 + b1)
    if min_order1 >= 0:
        return 'Yes'

    # Check order s2 + s1
    min_order2 = min(m2, m1 + b2)
    if min_order2 >= 0:
        return 'Yes'

    return 'No'
