def minPath(grid, k):
    N = len(grid)
    # Find the starting cell with the minimal value
    min_val = float('inf')
    start_x, start_y = 0, 0
    for i in range(N):
        for j in range(N):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                start_x, start_y = i, j

    path = [min_val]
    current_x, current_y = start_x, start_y

    for _ in range(k - 1):
        neighbors = []
        # Check all four possible directions
        if current_x > 0:
            neighbors.append((current_x - 1, current_y))
        if current_x < N - 1:
            neighbors.append((current_x + 1, current_y))
        if current_y > 0:
            neighbors.append((current_x, current_y - 1))
        if current_y < N - 1:
            neighbors.append((current_x, current_y + 1))

        # Find the neighbor with the smallest value
        min_next_val = float('inf')
        best_x, best_y = current_x, current_y
        for x, y in neighbors:
            if grid[x][y] < min_next_val:
                min_next_val = grid[x][y]
                best_x, best_y = x, y

        current_x, current_y = best_x, best_y
        path.append(min_next_val)

    return path
```

